'use client'

import { useState } from 'react'
import Link from '@/components/ui/Link'

type FAQ = { frage: string; antwort: string; kategorie: string }

const FAQS: FAQ[] = [
  // Allgemein
  { kategorie: 'Allgemein', frage: 'Wie logge ich mich ein?', antwort: 'Rufe https://software112.icp-consultants.at auf und melde dich mit deiner E-Mail-Adresse und deinem Passwort an. Alternativ funktioniert der Login auch mit Microsoft 365. Falls du dein Passwort vergessen hast, nutze „Passwort vergessen“ auf der Login-Seite – du bekommst einen Link per E-Mail.' },
  { kategorie: 'Allgemein', frage: 'Wie ändere ich mein Passwort?', antwort: 'Oben rechts im Benutzermenü auf „Mein Profil“ – dort unter „Passwort ändern“ das aktuelle und zweimal das neue Passwort eingeben (mindestens 12 Zeichen mit Buchstaben und Ziffern; bekannt gewordene Passwörter werden abgelehnt). Wer sich mit Microsoft 365 anmeldet, verwaltet sein Passwort bei Microsoft.' },
  { kategorie: 'Allgemein', frage: 'Ich habe das Fenster mit den Neuerungen weggeklickt – wo finde ich es wieder?', antwort: 'Unter System > Neuerungen stehen alle Release Notes zum Nachlesen, neueste zuerst. Das Fenster nach dem Einstieg erscheint pro Benutzer nur einmal je Version.' },
  { kategorie: 'Allgemein', frage: 'Welche Browser werden unterstützt?', antwort: 'software:112 funktioniert mit allen modernen Browsern (Chrome, Firefox, Edge, Safari). Für mobilen Einsatz empfehlen wir Chrome auf Android oder Safari auf iOS.' },
  { kategorie: 'Allgemein', frage: 'Kann ich die App am Handy verwenden?', antwort: 'Ja! Die Oberfläche ist für Tablets und Smartphones optimiert. Telefonnummern können direkt angetippt werden um einen Anruf zu starten.' },
  { kategorie: 'Allgemein', frage: 'Wie installiere ich software:112 als App am Handy oder Tablet?', antwort: 'software:112 lässt sich wie eine App auf den Startbildschirm legen – ohne App-Store.\n\nAndroid (Chrome): software112.icp-consultants.at öffnen, oben rechts im Menü (⋮) „App installieren“ bzw. „Zum Startbildschirm hinzufügen“ wählen. Lange auf das neue Symbol drücken öffnet Schnellzugriffe (Lese erfassen, Maßnahme erfassen, Kellerbuch).\n\niPhone/iPad – nur in der Safari-App: Ein Link aus Mail, Teams oder WhatsApp öffnet sich oft im eingebauten Browser dieser App, dort fehlt die Funktion. Darum Safari selbst öffnen (Kompass-Symbol) und software112.icp-consultants.at eintippen.\n• iOS 26 und neuer: neben der Adressleiste auf „•••“ tippen → „Teilen“ → im Teilen-Fenster nach unten wischen → „Zum Home-Bildschirm“ → „Als Web-App öffnen“ eingeschaltet lassen → „Hinzufügen“.\n• iOS 17/18: unten in der Mitte auf das Teilen-Symbol (Quadrat mit Pfeil nach oben; ist die Leiste ausgeblendet, kurz nach oben wischen) → ganz nach unten wischen → „Zum Home-Bildschirm“ → „Hinzufügen“.\n• Fehlt „Zum Home-Bildschirm“: ganz unten im Teilen-Fenster „Aktionen bearbeiten …“ öffnen und beim Eintrag auf das grüne + tippen.\nDanach über das neue Symbol „software:112“ starten. Die App hat am iPhone ihre eigene Anmeldung: beim ersten Start einmal mit E-Mail, Passwort und – falls eingerichtet – dem Zwei-Faktor-Code anmelden.\n\nAm PC (Chrome/Edge): rechts in der Adressleiste auf das Installieren-Symbol klicken (Bildschirm mit Pfeil).\n\nFür die Arbeit ist weiterhin eine Internetverbindung nötig.' },

  // Stornieren & Löschen (KAN-151, Stand 01.10.2026)
  { kategorie: 'BKI-Schnittstelle', frage: 'Wo finde ich alle Blätter der BKI-Schnittstelle?', antwort: 'Unter Kellerbuch > BKI-Schnittstelle (Reiter Lagerstand, Lagerbewegungen, Betriebsdaten & Gebinde, Weingärten, Rückverfolgung (RV), Verkauf/Einkauf/TBS und Gesamtexport & Kataloge); besondere Konten unter Kellerbuch > Besondere Konten, die BSM unter Auswertungen > Bestandsmeldung (BSM). Jedes Blatt gibt es als CSV, alle zusammen als XLSX im Reiter „Gesamtexport & Kataloge“.' },
  { kategorie: 'BKI-Schnittstelle', frage: 'Was bedeutet der Prüfbericht im Gesamtexport?', antwort: 'Er steht als erstes Blatt in der XLSX-Datei und nach „Prüfen“ auf der Seite: je Blatt die Zeilenzahl und Hinweise – fehlende Mindestangaben (etwa eine Lagerbewegung ohne Buchungsart BSM), ungültige Werte (Zelle bleibt leer), auf die Länge der Spezifikation gekürzte Texte und nicht numerische Belegnummern. Fehler vor der Abgabe in den Stammdaten bzw. Buchungen korrigieren und neu exportieren.' },
  { kategorie: 'BKI-Schnittstelle', frage: 'Warum stehen die RV-Blätter nicht im Gesamtexport?', antwort: 'RV zum Eingang und RV zum Ausgang gelten immer für eine bestimmte Charge, ein Grundstück oder eine Füllung. Sie werden deshalb einzeln im Reiter „Rückverfolgung (RV)“ abgerufen; der Prüfbericht weist darauf hin.' },
  { kategorie: 'BKI-Schnittstelle', frage: 'Das Dashboard meldet „Das Bewegungsjournal weicht … ab“ – was tun?', antwort: 'Unter Kellerbuch > Journal stehen die betroffenen Chargen und Füllungen mit Ist-Bestand, Journal-Saldo und Differenz. Meist stammt die Abweichung aus Altdaten vor dem Journalbeginn oder aus einer direkten Korrektur. Bestandsmeldung und BKI-Schnittstelle rechnen mit dem Journal – die Abweichung daher vor der Abgabe klären (z. B. über Inventur bzw. Zugangskorrektur).' },
  { kategorie: 'BKI-Schnittstelle', frage: 'Woher kommen die Kürzel für Erzeugnis, Qualitätsstufe und Buchungsart?', antwort: 'Die Qualitätsstufen sind die amtlichen BKI-Kürzel; für Erzeugnis und Buchungsart hat die BKI keine Liste, software:112 verwendet eigene, vorläufige Kürzel. Alle stehen im Reiter „Gesamtexport & Kataloge“ (vorläufige mit *) und als CSV.' },
  { kategorie: 'Stornieren & Löschen', frage: 'Warum werden Buchungen storniert statt gelöscht?', antwort: 'Was in Aufzeichnungen und Behördenmeldungen eingeht, wird seit 30.09.2026 storniert, nicht gelöscht: im Kellerbuch Umzüge, Schwund, Verschnitte, Kellerbehandlungen, Füllungen und Zukäufe; bei der Lese Lesemengen, Pressungen und Traubenverkäufe; Verkäufe; in der E&A Buchungen, Zahlungen und Umbuchungen; dazu DAC-Anträge, Weinanalysen, Prüfnummernanträge, Transportbescheinigungen und Exportaufträge. Beim Stornieren (Storno-Symbol bzw. „Stornieren“) ist ein Grund Pflicht – mindestens 10 Zeichen. Die Zeile bleibt mit Zeitpunkt, Benutzer und Grund gekennzeichnet stehen, zählt aber in keiner Menge und keinem Bestand; Listen und Meldungen zeigen sie als storniert. Das BKI-Datenblatt (CSV) enthält stornierte Traubenverkäufe nicht. Ein Storno lässt sich nicht zurücknehmen – bei Bedarf neu erfassen. Stornieren dürfen Betriebs-Manager, Super-Admin und Mitarbeiter mit dem passenden Schreibmodul.' },
  { kategorie: 'Stornieren & Löschen', frage: 'Kann ich einen stornierten Eintrag endgültig löschen?', antwort: 'Ja, aber nur bei Fehleinträgen und nur, wenn er schon storniert ist: Bei stornierten Zeilen (z. B. Umzug, Kellerbehandlung, Analyse, Lese, Pressung, Traubenverkauf) steht statt des Storno-Symbols der Mülleimer „Endgültig löschen“, auf Detailseiten wie DAC-Antrag, Prüfnummernantrag, Transportbescheinigung oder Exportauftrag in der Storno-Karte. Auch hier ist ein Grund Pflicht (mindestens 10 Zeichen); Grund und Benutzer werden im Änderungsprotokoll festgehalten. Endgültig löschen dürfen Betriebs-Manager, Super-Admin und Mitarbeiter mit dem passenden Schreibmodul. Manches bleibt auch storniert als Nachweis stehen, z. B. ein DAC-Antrag mit Füllungen oder Prüfnummernantrag, ein Traubenverkauf mit Rechnungsposition, eine Pressung, an deren Chargen noch Buchungen hängen, sowie Lese, Pressungen und Traubenverkäufe eines Jahrgangs mit eingereichter AMA-Erntemeldung. Verkäufe und E&A-Buchungen, Zahlungen und Umbuchungen werden nie gelöscht. Entwürfe ohne Bezug – DAC-Antrag oder Exportauftrag im Status Entwurf – kann die Betriebsleitung direkt mit „Entwurf löschen“ (mit Grund) entfernen; einen Exportauftrag nur ohne ausgestellte Dokumente und ARC-Nummer.' },
  { kategorie: 'Stornieren & Löschen', frage: 'Warum kann ich eine Ried, ein Grundstück oder einen Kontakt nicht löschen?', antwort: 'Stammdaten mit Bezug – z. B. eine Ried oder ein Grundstück mit Maßnahmen, Lese oder Chargen, ein Kontakt oder eine Firma mit Verkäufen oder Zukäufen – lassen sich nur noch deaktivieren: Beim Löschen nennt software:112 den Bezug und fragt „Stattdessen deaktivieren?“. Ohne Bezug wird weiterhin gelöscht. Deaktivierte Datensätze bleiben auf bestehenden Belegen und in der Historie, erscheinen aber nicht mehr in Auswahllisten. Unter CRM > Kontakte bzw. Firmen blendet „Inaktive anzeigen“ sie ein, deaktivierte Rieden und Grundstücke stehen ausgegraut bzw. als „deaktiviert“ in der Rieden-Übersicht. Reaktivieren ist jederzeit möglich. Ein Grundstück deaktivierst du mit Datum (ab wann es nicht mehr bewirtschaftet wird): Meldungen für frühere Zeiträume zählen es bis dahin weiter. Rieden und Grundstücke löschen bzw. deaktivieren Betriebs-Manager und Super-Admin.' },
  { kategorie: 'Stornieren & Löschen', frage: 'Wo sehe ich Stornos und Löschungen?', antwort: 'Stornierte Einträge stehen direkt in den Listen – gekennzeichnet mit Datum, Benutzer und Grund – sowie im Bewegungsbuch, im Weinbuch und in den Meldungen. Alles zusammen, also Stornos, endgültige Löschungen und nachträgliche Änderungen in Kellerbuch, Lese, Verkauf, E&A und Stammdaten, enthält das Änderungs- und Löschprotokoll: unter Kellerbuch > Gebinde die Karte „Änderungs- und Löschprotokoll“ mit „Protokoll als CSV“ (Zeitraum wählbar) oder unter Übersicht > Meldungen & Fristen in der Karte „Behördenmeldungen (Drucken & CSV)“. Je Eintrag stehen Zeitpunkt, Bereich, Aktion (Änderung oder Löschung), alte und neue Werte – ein Storno erscheint als Änderung samt Storno-Grund – und der Benutzer. Abrufen dürfen das Protokoll nur Betriebs-Manager und Super-Admins.' },

  // CRM
  { kategorie: 'CRM', frage: 'Was ist der Unterschied zwischen Lead und Kunde?', antwort: 'Neue Kontakte starten automatisch als Lead (gelbes Badge). Sobald der erste Verkauf gebucht wird, wechselt der Status automatisch auf Kunde (grünes Badge). Der Toggle kann auch manuell umgestellt werden.' },
  { kategorie: 'CRM', frage: 'Wie finde ich schnell einen bestimmten Kontakt?', antwort: 'Nutze die Suchleiste oben in der Kontaktliste (Name, Accountnummer, E-Mail, Telefon, Ort) oder den Alphabetfilter A-Z darunter. Segment-Filter und Sortierung nach Vor-/Nachname ebenfalls verfügbar. Die Liste zeigt die ersten 100 Treffer, "Mehr anzeigen" lädt weitere; Suche und Filter stehen in der Adresszeile und bleiben beim Zurück-Navigieren erhalten. Am schnellsten geht es über Strg K (Befehlspalette).' },
  { kategorie: 'CRM', frage: 'Warum zeigt die Kontaktliste nur 100 Einträge?', antwort: 'Seit dem Datenimport (mehrere tausend Kontakte und Firmen) werden die Listen serverseitig gefiltert und seitenweise geladen – die Seite baut sich damit in unter einer Sekunde auf. Der Zähler oben rechts nennt den Gesamtbestand, unter der Liste steht "x von y angezeigt"; "Mehr anzeigen" lädt jeweils 100 weitere. Wer alle braucht, nutzt den Export.' },
  { kategorie: 'E-Mail', frage: 'Warum stand in einer E-Mail nur Text wie "Obsah obrázku …" statt eines Bildes?', antwort: 'Das war der Alternativtext eingebetteter Signaturbilder, die noch nicht aus dem Postfach geladen wurden. Eingebettete Bilder werden jetzt beim Öffnen mitgeholt und angezeigt; echte Anhänge erscheinen als Schaltflächen über dem Text zum Herunterladen.' },
  { kategorie: 'CRM', frage: 'Der Morgenbericht meldet mögliche Kontakt-Dubletten – was tun?', antwort: 'Klick auf den Befund führt zu CRM > Kontakte > Dubletten. Dort stehen die Gruppen mit gleicher E-Mail oder gleichem Namen samt Aktivitäten- und Verkaufszahlen. Behaltenen Kontakt wählen, die anderen anhaken und „Zusammenführen“: Alle Verknüpfungen wandern auf den behaltenen Kontakt, die anderen werden deaktiviert (nicht gelöscht). Die Stufe hilft beim Priorisieren: „sicher“ zuerst, „prüfen“ ansehen, „unwahrscheinlich“ (zwei verschiedene Personen mit gemeinsamer Adresse) lässt sich gesammelt als „keine Dublette“ markieren – die Gruppen werden dann nicht mehr gemeldet.' },
  { kategorie: 'CRM', frage: 'Wie plane ich einen Außendienstbesuch?', antwort: 'Unter Auswertungen > Besuchsplanung: Region eingeben, Segment wählen (z.B. Gastronomie), dann "Planen". Das Ergebnis zeigt PLZ-geclusterte Kontakte mit Ampelfarbe (letzter Kontakt). Klick auf "In Maps öffnen" startet die Route.' },
  { kategorie: 'CRM', frage: 'Warum erscheint eine E-Mail nicht beim Kontakt?', antwort: 'E-Mails werden dem Kontakt oder der Firma zugeordnet, wenn der Absender bzw. Empfänger erkannt wird: über die Standard- oder eine der weiteren E-Mail-Adressen des Datensatzes oder über die Firmendomain (jede Adresse @firma.at gehört zur Firma, nicht bei gmx/gmail & Co.). Die Zuordnung läuft automatisch über die Spiegelung (täglich 7 Uhr für alle verbundenen Postfächer, zusätzlich beim Öffnen von Nachrichten alle 15 Minuten für das eigene Postfach) und sofort beim Öffnen einer E-Mail. Fehlt eine Mail: prüfen, ob die Adresse am Datensatz steht (ggf. unter "Weitere E-Mail-Adressen" ergänzen) und ob das betroffene Postfach in diesem Betrieb verbunden ist.' },
  { kategorie: 'CRM', frage: 'Ein Kunde schreibt von einer neuen E-Mail-Adresse – was passiert?', antwort: 'Passt der Anzeigename zu einem bestehenden Kontakt oder einer Firma, zeigt Nachrichten beim Öffnen den Hinweis "im CRM gibt es bereits einen Eintrag mit diesem Namen unter anderer Adresse". Mit "Ja, zu … hinzufügen" wird die neue Adresse als weitere E-Mail gespeichert (hat der Datensatz noch keine Adresse, wird sie Standardadresse), und die Mail wird ab sofort zugeordnet. Mit "Nein, neuer Lead" legst du stattdessen einen neuen Lead an.' },
  { kategorie: 'CRM', frage: 'Wie lege ich aus einer E-Mail einen Lead an?', antwort: 'E-Mail unter Nachrichten öffnen. Ist der Absender unbekannt, erscheint über der Mail die Frage "Soll ein Lead angelegt werden?" – "Ja" öffnet den Dialog, die KI belegt Name, Telefon, Position, Firma und Adresse aus der Signatur vor und fasst das Anliegen zusammen. Segment, Firma (neu/bestehend/keine), Rabattgruppe und Zahlungsziel wählst du im Dialog, dann "Als Lead speichern". Der Kontakt bekommt eine Accountnummer, die E-Mail liegt in seiner Historie.' },
  { kategorie: 'CRM', frage: 'Die Lead-Frage nervt bei Newslettern – wie werde ich sie los?', antwort: 'Im Frage-Balken "Nein, nicht mehr fragen" klicken: der Absender wird für deinen Betrieb gemerkt und löst keine Frage mehr aus. Typische Systemadressen (noreply, newsletter, mailer-daemon) und die eigenen Postfächer werden ohnehin übersprungen. "Jetzt nicht" blendet die Frage nur für die aktuelle Sitzung aus.' },
  { kategorie: 'CRM', frage: 'Wo finde ich die Notizen zu einem Kontakt?', antwort: 'In der Kontaktdetailansicht gibt es eine eigene Notizen-Karte unter den Kontaktdaten. Offene Notizen erscheinen zuerst, erledigte darunter.' },
  { kategorie: 'CRM', frage: 'Kann ich meinen Outlook-Kalender im CRM sehen?', antwort: 'Ja. Sobald du deine Mailbox unter Nachrichten mit Microsoft 365 verbindest, werden deine persönlichen Outlook-Termine automatisch – hellblau markiert mit eigenem "Outlook"-Label – zusätzlich zu deinen CRM-Terminen im Kalender (Woche/Monat/Jahr) angezeigt. Klick auf einen Outlook-Termin öffnet ein Detailfenster mit Link "In Outlook öffnen".' },
  { kategorie: 'CRM', frage: 'Warum sehe ich (noch) keine Outlook-Termine im CRM-Kalender?', antwort: 'Entweder ist deine Mailbox noch nicht verbunden (Nachrichten > "Mit Microsoft 365 verbinden"), oder deine bestehende Verbindung ist älter als die Kalenderfreigabe – in dem Fall unter Nachrichten > Einstellungen einmalig "Trennen & neu verbinden" klicken, damit die neue Berechtigung zum Kalenderzugriff wirksam wird.' },

  // Warenwirtschaft
  { kategorie: 'Warenwirtschaft', frage: 'Warum kann ich keinen Verkauf ohne Kontakt anlegen?', antwort: 'Ein Verkauf muss immer einem Kontakt oder einer Firma zugeordnet werden. Falls der Käufer noch nicht angelegt ist, zuerst einen neuen Kontakt oder eine Firma erstellen.' },
  { kategorie: 'Warenwirtschaft', frage: 'Wie storniere ich eine Rechnung?', antwort: 'In der Verkaufsdetailansicht oben auf das Storno-Symbol „Verkauf stornieren“ klicken und einen Grund angeben (Pflicht, mindestens 10 Zeichen). Der Bestand wird automatisch zurückgebucht (Flaschen in die Füllung, offener Wein in die Kellerbuch-Charge – eine inzwischen abgeschlossene Charge wird dabei wieder aktiv), verknüpfte Traubenverkäufe (BKI) werden mitstorniert. Die Rechnung bleibt mit Datum, Benutzer und Grund als "Storniert" sichtbar; Verkäufe werden nie gelöscht, die Rechnungsnummern bleiben lückenlos. Bezahlte Beträge bleiben als Einnahme stehen – nur mit „Erstattet am“ werden die Zahlungen an diesem Tag storniert und in der E&A gegengebucht. Klappt die Rückbuchung nicht (z. B. Gebinde inzwischen von einem Partnerbetrieb belegt), wird nichts geändert und der Grund angezeigt. Rechnungen mit offenem Wein (Tank) dürfen nur Betriebs-Manager und Mitarbeiter mit Freigabe Kellerbuch (oder Rieden) stornieren.' },
  { kategorie: 'Warenwirtschaft', frage: 'Warum kann ich keinen Tankverkauf speichern?', antwort: 'Offener Wein wird immer aus einer Kellerbuch-Charge verkauft – beim Speichern wird die Menge von der Charge abgebucht. Dafür braucht es zusätzlich zur Warenwirtschaft die Freigabe Kellerbuch (oder Rieden). Mitarbeiter mit der Vorlage "Vertrieb" können Flaschen verkaufen, Tankverkäufe aber nicht. Zukäufe ohne Gebinde bitte zuerst über "Zukauf bearbeiten" einem Gebinde zuordnen – dabei entsteht die Charge.' },
  { kategorie: 'Warenwirtschaft', frage: 'Wie korrigiere ich den Flaschenbestand einer Füllung?', antwort: 'In der Füllungsbearbeitung unten unter "Bestand korrigieren": Inventur (gezählter Ist-Bestand), Bruch, Eigenverbrauch, Schwund oder Korrektur mit Datum und Grund buchen. Der Bestand wird nicht mehr überschrieben – jede Änderung bleibt als datierte Buchung sichtbar. Anzahl, Flaschengröße und Füllmenge sind fest, sobald es Verkäufe oder Bestandsbuchungen gibt.' },
  { kategorie: 'Warenwirtschaft', frage: 'Was ist ein Stornobeleg und warum hat er ein eigenes Datum?', antwort: 'Seit 27.10.2026 storniert software:112 eine Rechnung über einen eigenen Stornobeleg (Stornorechnung ST-…) mit negativen Beträgen. Die ursprüngliche Rechnung bleibt in ihrem Monat unverändert – auch wenn dieser Monat schon abgeschlossen oder die UVA übermittelt ist –, der Stornobeleg bucht am Storno-Datum gegen. Das Storno-Datum wählst du im Storno-Dialog (vorbelegt heute, nicht vor dem Rechnungsdatum, nicht im gesperrten Zeitraum). Rechnungsjournal, UVA, BMD-Export und Umsatzauswertungen zeigen beide Belege, offen bleibt keiner. Den Stornobeleg kannst du drucken und als PDF per E-Mail an den Kunden schicken.' },
  { kategorie: 'Warenwirtschaft', frage: 'Warum kann ich eine Füllung nicht mehr löschen oder stornieren?', antwort: 'Eine Füllung wird nicht gelöscht, sondern storniert (Storno-Symbol in der Lagerliste, Grund mindestens 10 Zeichen) – und das nur, solange es keine Verkäufe und keine Bestandsbuchungen gibt. Dann werden die abgefüllten Liter (und ein beim Abfüllen gebuchter Abschluss-Schwund) auf die Charge zurückgebucht; die Füllung verschwindet aus dem Lager, bleibt aber im Bewegungsbuch und im Weinbuch als storniert stehen. Gibt es Verkäufe oder Bestandsbuchungen, bleibt sie als Historie erhalten; der Knopf ist ausgegraut und nennt den Grund. Ausverkaufte Füllungen (Bestand 0) blendet das Lager standardmäßig aus – über "Ausverkaufte Füllungen einblenden" lassen sie sich anzeigen.' },
  { kategorie: 'Warenwirtschaft', frage: 'Kann ich Rabatt oder Sonderrabatt bei einem Verkauf abwählen?', antwort: 'Ja. Rabatt (aus der Rabattgruppe) und Sonderrabatt (aus dem Kontakt/der Firma) werden automatisch vorbelegt, können aber pro Position direkt auf 0 gesetzt oder geändert werden. Einfach den Wert im Positionsformular überschreiben.' },
  { kategorie: 'Warenwirtschaft', frage: 'Wie hinterlege ich Skonto für einen Kunden?', antwort: 'Im Kontakt- oder Firmendatensatz unter CRM gibt es ein Skonto-Feld (in Prozent). Dieser Wert wird automatisch in neue Verkäufe übernommen und auf der Rechnung ausgewiesen. Im Verkaufsformular kann Skonto jederzeit angepasst oder auf 0 gesetzt werden.' },
  { kategorie: 'Warenwirtschaft', frage: 'Wie erfasse ich eine Teilzahlung?', antwort: 'Im Verkaufsdetail gibt es den Bereich Zahlungen. Klick auf "Teilzahlung buchen": Betrag und Datum eingeben und speichern. Der offene Restbetrag wird sofort aktualisiert. Du kannst beliebig viele Teilzahlungen erfassen; der Posten gilt als vollständig bezahlt sobald der Gesamtbetrag erreicht ist.' },
  { kategorie: 'Warenwirtschaft', frage: 'Wie wähle ich den USt.-Satz pro Verkaufsposition?', antwort: 'Bei jeder Verkaufsposition ist der USt.-Satz einzeln wählbar (0 %, 10 %, 13 %, 20 %). Der Standard-USt.-Satz kommt aus den Mandanten-Einstellungen (Admin > Mandant > Verkauf) und wird automatisch vorbelegt – du kannst ihn aber pro Position überschreiben. Das ist nützlich wenn du z.B. Weinflaschen (13 %) und Serviceleistungen (20 %) in einer Rechnung kombinierst.' },

  { kategorie: 'Warenwirtschaft', frage: 'Wie erfasse ich einen Traubenverkauf?', antwort: 'Unter Warenwirtschaft > Verkauf > Neuer Verkauf den Positionstyp Weintrauben (kg) wählen. Ried auswählen – nur Riede mit verfügbaren Trauben (Ernte minus Pressungen minus bereits verkaufte Menge) werden angezeigt. Die Lese (z. B. 2026/1 Hauptlese oder 2026/2 Eiswein) ist mit der neuesten Lese der Ried vorbelegt; verfügbar ist, was in dieser Lese gelesen und noch nicht verpresst oder verkauft ist. Mostgewicht und Qualitätsstufe werden aus dieser Lese vorbelegt – das Mostgewicht als Messwert mit Einheit (°KMW oder °Oe, die andere Einheit umgerechnet mit ≈); ändern kannst du es in beiden Einheiten, die bevorzugte steht zuerst (System > Mein Betrieb, Reiter „Kellerwirtschaft“ – Betriebs-Manager). Menge, Preis/kg und Gesundheit (G/K) eingeben. Beim Speichern werden Liefernummer und Rechnungsnummer automatisch vergeben.' },
  { kategorie: 'Warenwirtschaft', frage: 'Was passiert beim Stornieren eines Traubenverkaufs?', antwort: 'Beim Stornieren der Rechnung wird auch der verknüpfte BKI-Traubenverkauf storniert – er bleibt mit Datum, Benutzer und Grund sichtbar (Liefernummer bleibt), zählt aber in keiner Menge und fehlt im BKI-Datenblatt (mit Hinweis). Die kg sind wieder verfügbar und erscheinen in der Ried-Auswahl, wenn ein neuer Verkauf angelegt wird. Endgültig löschen lässt sich ein stornierter Traubenverkauf nur ohne Rechnungsposition.' },
  { kategorie: 'Warenwirtschaft', frage: 'Was passiert automatisch beim Erfassen eines Zukaufs?', antwort: 'Wählst du beim Zukauf (Kellerbuch > Zukauf) ein Zielgebinde, legt software:112 automatisch eine neue Weinausbau-Charge mit Weinart, Rebsorte, Qualitätsstufe und Einstandspreis/Liter an. Bei Einheit „L" wird der Einstandspreis/Liter zusätzlich automatisch aus Gesamtpreis ÷ Menge berechnet.' },
  { kategorie: 'Warenwirtschaft', frage: 'Wann öffnet sich nach einem Zukauf automatisch das Verschneiden-Formular?', antwort: 'Immer dann, wenn im gewählten Zielgebinde bereits eine andere Rebsorte liegt, oder wenn zwar dieselbe Rebsorte, aber eine andere Qualitätsstufe vorhanden ist. Du wirst dann direkt zum Verschneiden-Formular der bestehenden Charge weitergeleitet, mit Quelle und Menge vorbelegt.' },

  // E-Mail
  { kategorie: 'E-Mail', frage: 'Wie verbinde ich meine Mailbox?', antwort: 'Unter Nachrichten: "Mit Microsoft 365 verbinden" klicken und mit dem Weingut-Outlook-Konto anmelden. Jeder Benutzer verbindet sein eigenes Konto – die Verbindung ist persönlich, nicht geteilt.' },
  { kategorie: 'E-Mail', frage: 'Was ist eine Shared Mailbox und wie richte ich sie ein?', antwort: 'Eine Shared Mailbox ist eine gemeinsam genutzte E-Mail-Adresse (z.B. office@weingut.at). Unter Nachrichten > Einstellungen: Adresse eintragen und speichern. Voraussetzung: dein Exchange-Administrator muss dir "Send As"-Rechte auf die Shared Mailbox geben.' },
  { kategorie: 'E-Mail', frage: 'Werden E-Mails dauerhaft gespeichert?', antwort: 'Ja. Einmal täglich werden Posteingang und Gesendet aller verbundenen Postfächer ins CRM gespiegelt: Mails von oder an bekannte Kontakte/Firmen landen als Aktivität (erster Lauf 90 Tage rückwirkend, danach nur Neues). Öffnest du eine E-Mail in /nachrichten, wird sie sofort gespeichert. Der Inhalt bleibt unter den Aktivitäten des Kontakts abrufbar – auch wenn die Mail in der Mailbox gelöscht wird.' },
  { kategorie: 'E-Mail', frage: 'Ich sehe nur die neuesten Nachrichten – wo sind die älteren?', antwort: 'Die Liste zeigt 50 Nachrichten je Ordner; unten in der Liste holt "Ältere Nachrichten laden" jeweils 50 weitere, so weit zurück wie das Postfach reicht. Unterordner erscheinen eingerückt in der Ordnerliste.' },
  { kategorie: 'E-Mail', frage: 'Wie antworte ich allen und nehme die Originalnachricht mit?', antwort: '"Allen antworten" setzt Absender plus alle weiteren Empfänger aus An und CC (ohne deine eigene Adresse); An und CC kannst du vor dem Senden ändern. Bei "Antworten" und "Allen antworten" geht die Originalnachricht zitiert unter deinem Text mit und die Antwort bleibt im selben Thread.' },
  { kategorie: 'Allgemein', frage: 'Änderungen erscheinen erst nach "Seite neu laden"?', antwort: 'software:112 aktualisiert die Daten jetzt selbst: beim Zurückkehren in den Tab, bei Browser-Zurück und alle drei Minuten im Hintergrund – Formulareingaben bleiben dabei erhalten. Wenn du etwas vermisst, einmal in einen anderen Tab und zurück wechseln genügt.' },
  { kategorie: 'E-Mail', frage: 'Warum sehe ich "Aktualisieren" und "Einstellungen" nicht?', antwort: 'Diese Buttons befinden sich am unteren Ende der Ordner-Sidebar. Falls du viele Ordner hast, scrolle im linken Bereich nach unten.' },
  { kategorie: 'E-Mail', frage: 'Ich sehe nach dem Löschen eine E-Mail noch kurz – ist das normal?', antwort: 'Die E-Mail wird sofort aus der Ansicht entfernt. Falls sie kurz wieder erscheint und dann weg ist, handelt es sich um ein kurzes Cache-Phänomen. Die E-Mail ist tatsächlich in "Gelöschte Elemente" verschoben.' },

  // Weinexport
  { kategorie: 'Weinexport', frage: 'Welche Exportdokumente kann software:112 generieren?', antwort: 'EUR.1 Warenverkehrsbescheinigung, CMR Internationaler Frachtbrief, Certificate of Origin, Packliste, Lieferschein (DE/EN), Exportrechnung/Commercial Invoice und Proforma (DE/EN) – jeweils als Druckansicht. Das „Weinbegleitdokument (altes Muster)“ – früher „V1/V2“ – bleibt druckbar, entspricht aber nicht dem geltenden Recht und wird ersetzt.' },
  { kategorie: 'Weinexport', frage: 'Was ist das EMCS und wie nutze ich es in software:112?', antwort: 'EMCS (Excise Movement and Control System) ist das elektronische System der Zollverwaltung für Beförderungen verbrauchsteuerpflichtiger Waren, auch Wein. software:112 übermittelt nichts an EMCS. Am Exportauftrag öffnest du unter "EMCS" das Datenblatt mit den Angaben zum Erfassen in EMCS (auch als CSV) und trägst danach ARC-Nummer und Status ein.' },
  { kategorie: 'Weinexport', frage: 'Was bedeuten die Incoterms?', antwort: 'Incoterms regeln wer Transportkosten und Risiko trägt. Häufige Werte: EXW (ab Werk, Käufer zahlt alles), DAP (geliefert am Bestimmungsort, du zahlt Transport), CIF (du zahlt Transport + Versicherung bis Zielhafen). Die Wahl beeinflusst das Exportdokument.' },

  // KI
  { kategorie: 'KI-Modul', frage: 'Was kann ich "Frag dein Weingut" fragen?', antwort: 'Alles rund um deine Betriebsdaten: Kontakte nach Segment/Region, Weinbestände, offene Rechnungen, Kellerchargen, Behandlungen, Pipeline-Einträge. Formuliere in natürlicher Sprache auf Deutsch, z.B. "Welche Gastro-Kunden kommen aus Deutschland?"' },
  { kategorie: 'KI-Modul', frage: 'Was passiert wenn mein KI-Limit erschöpft ist?', antwort: 'Du bekommst eine Meldung mit aktuellem Verbrauch und Limit (Basis 50, Standard 100, Premium unbegrenzt pro Monat). Das Limit setzt sich automatisch am Monatsersten zurück; der Morgenbericht erscheint dann ohne KI-Zusammenfassung, die Befunde bleiben. Ein Upgrade geht über Mein Betrieb > Abo & Paket.' },
  { kategorie: 'KI-Modul', frage: 'Kann ich die Ertragshistorie meiner Rieden über mehrere Jahre abfragen?', antwort: 'Ja. Frage z.B. "Wie viel kg wurden 2022 auf Grundstück 45 geerntet?" oder "Zeig mir die Ertragshistorie je GST der letzten Jahre" – die KI liefert Erntemenge, Fläche und Ertrag in kg/ha je Grundstück und Jahrgang.' },

  // Buchhaltung
  { kategorie: 'Buchhaltung', frage: 'E&A oder Doppik – was ist der Unterschied in software:112?', antwort: 'E&A: Die Einnahmen-Ausgaben-Rechnung läuft komplett in software:112 – Buchungen, Belege, UVA-Berechnung, Monatsabschluss, Finanzübersicht. Doppik: Die doppelte Buchhaltung führt die Steuerberatung in BMD; software:112 ist das Vorsystem, in dem Rechnungen und Belege erfasst und per BMD-Übergabe weitergegeben werden. Der Bereich heißt dann "Belege & BMD", UVA ist nur Vorschau, Monatsabschluss entfällt. Die Wahl trifft der Betriebs-Manager beim Paketwechsel oder unter Mein Betrieb > Abo & Paket.' },
  { kategorie: 'Buchhaltung', frage: 'Warum kann ich bei Doppik keinen Monatsabschluss machen und keine AfA buchen?', antwort: 'Weil die Buchhaltung bei der Steuerberatung liegt: Sperren, Abschlüsse und die Abschreibung bucht die Kanzlei in BMD. software:112 liefert Belege und den Anlagenspiegel als Beilage – so entsteht nichts doppelt.' },
  { kategorie: 'Buchhaltung', frage: 'Wie übergebe ich Belege an meine Steuerberatung (BMD)?', antwort: 'Unter E&A-Rechnung > BMD-Übergabe (bei Doppik direkt hinter den Buchungen): Zeitraum wählen, "nur neue" lassen, Buchungsstapel erzeugen. Die CSV-Datei im BMD-NTCS-Format samt Belegdokumenten schickst du der Kanzlei; das Konten-Mapping (Erlöskonten, Sammelkonten, Steuercodes) kannst du vorher mit der Kanzlei abstimmen und im Tab Konten-Mapping anpassen. Jede Übergabe wird protokolliert.' },
  { kategorie: 'Buchhaltung', frage: 'Was zeigt die Finanzübersicht und was bedeutet "Ergebnis nach AfA"?', antwort: 'Die Finanzübersicht zeigt Ergebnis, Einnahmen, Ausgaben, Liquidität, Forderungen, UVA- und Abschlussstand gegen das Vorjahr. "Ergebnis (Einnahmen − Ausgaben)" ist die zahlungswirksame Sicht. "Ergebnis nach AfA" rechnet Anlagenkäufe (Kategorie Anlagenkauf, Kontenklasse 0) heraus und zieht stattdessen die Abschreibung laut Anlagenverzeichnis ab – eine vereinfachte steuerliche Sicht, verbindlich ist die Auswertung der Steuerberatung.' },
  { kategorie: 'Buchhaltung', frage: 'Wie erfasse ich eine Anschaffung wie Traktor oder Presse richtig?', antwort: 'Zuerst als normale Ausgabe in der Kategorie "Anlagenkauf (aktivierungspflichtig)" buchen – so stimmen Vorsteuer und BMD-Übergabe. Dann unter E&A-Rechnung > Anlagen & AfA über "Anlage anlegen" (die Buchung wird angeboten) Nutzungsdauer und Methode setzen; der AfA-Plan erscheint sofort. Nach Jahresende bucht "AfA buchen" die Jahresabschreibung als Betriebsausgabe per 31.12.; die Fristen-Ampel erinnert bis 30.4.' },
  { kategorie: 'Buchhaltung', frage: 'Was ist ein GWG?', antwort: 'Geringwertige Wirtschaftsgüter bis 1.000 € netto dürfen im Jahr der Anschaffung voll abgeschrieben werden (§ 13 EStG). Im Anlagenformular wählst du dafür die Methode "GWG – Sofortabschreibung"; über die Nutzungsdauer geht auch (Wahlrecht).' },
  { kategorie: 'Buchhaltung', frage: 'Wie funktioniert der SVS-Vergleich (Pauschalsystem oder Beitragsgrundlagenoption)?', antwort: 'Unter E&A-Rechnung > SV-Beiträge (SVS) hinterlegst du die Einheitswerte je Grundstück (manuell oder CSV-Import). software:112 rechnet daraus Versicherungswert und Beiträge im Pauschalsystem und stellt die Option gegenüber, bei der die tatsächlichen Einkünfte zählen (Vorschlag: Vorjahresergebnis nach AfA). Die Option wählt der Betriebs-Manager – der Antrag bei der SVS bleibt ein eigener Schritt, der Vergleich ist eine Entscheidungshilfe.' },
  { kategorie: 'Buchhaltung', frage: 'Warum kann ich eine Buchung nicht löschen oder bearbeiten – wie storniere ich sie?', antwort: 'E&A-Buchungen werden nicht gelöscht, sondern storniert (seit 1.10.2026): Symbol „Buchung stornieren“ in der Buchungsliste, Grund angeben (mindestens 10 Zeichen). Die Buchung bleibt gekennzeichnet stehen, eine Gegenbuchung mit negativem Betrag hebt sie auf – Summen, UVA und Journal stimmen damit, und der ursprüngliche Inhalt bleibt ersichtlich. Das geht auch, wenn der Monat abgeschlossen oder die UVA übermittelt ist: Die Gegenbuchung kommt dann auf den heutigen Tag. Bearbeiten ist in gesperrten Zeiträumen nicht möglich. Einnahmen aus Verkäufen stornierst du über die Zahlung im Verkauf, AfA-Buchungen unter Anlagen & AfA.' },
  { kategorie: 'Buchhaltung', frage: 'Warum werden Beträge als "€ 1.234,50" angezeigt?', antwort: 'Seit September 2026 gilt das Zahlenformat des Manuals überall: Tausenderpunkt, Dezimalkomma, Beträge mit zwei Nachkommastellen und dem €-Zeichen vorne. Mengen (Liter, Flaschen, Hektar) haben so viele Nachkommastellen wie nötig.' },

  // Abo & Paket
  { kategorie: 'Abo & Paket', frage: 'Was ist in welchem Paket enthalten?', antwort: 'Basis (€ 199/Monat, 1 Mandant, 1 Benutzer): Rieden, Kellerbuch, CRM, Morgenbericht, 50 KI-Abfragen. Standard (€ 299, bis zu 2 Mandanten, 5 Benutzer je Mandant): zusätzlich Newsletter, E&A-Rechnung mit BMD-Übergabe, Controlling, Wetter & Empfehlungen je Ried, 100 KI-Abfragen. Premium (€ 399, bis zu 5 Mandanten, unbegrenzt Benutzer): zusätzlich bot:112 mit Sprachsteuerung, Exportaufträge, unbegrenzte KI-Abfragen. Monatlich kündbar.' },
  { kategorie: 'Abo & Paket', frage: 'Wie viele Betriebe (Mandanten) sind im Paket enthalten?', antwort: 'Basis umfasst 1 Mandanten, Standard bis zu 2 und Premium bis zu 5 – den eigenen Betrieb mitgezählt, alles mit dem Monatsentgelt des Pakets abgegolten. Weitere Mandanten (z. B. eine GmbH neben dem Weingut) ordnet der Plattform-Admin deinem Betrieb als Submandanten zu; sie müssen nicht demselben Inhaber gehören, Vertragspartner bleibt dein Betrieb. Submandanten haben dasselbe Paket, das Benutzerlimit gilt je Mandant, CRM und Kellergebinde werden gemeinsam genutzt. Ein Wechsel in ein Paket mit weniger Mandanten geht erst, wenn die Submandanten dazu passen.' },
  { kategorie: 'Abo & Paket', frage: 'Wie wechsle ich das Paket?', antwort: 'Als Betriebs-Manager unter System > Mein Betrieb > Abo & Paket > "Paket wechseln". Bei Standard oder Premium fragt software:112 nach der Buchhaltungsart (E&A oder Doppik), dann geht es zur Zahlung. Zurück kommst du über "Zurück zu Mein Betrieb" oben auf der Abo-Seite.' },
  { kategorie: 'Abo & Paket', frage: 'Warum kann ich Module nicht einzeln ein- oder ausschalten?', antwort: 'Die Module werden vom Paket geführt – wer Standard bucht, bekommt genau die Standard-Module. Das hält die Pakete vergleichbar und die Abrechnung einfach. Einzige Ausnahme ist die Buchhaltungsart, die der Betrieb selbst wählt, und SumUp, das der Plattform-Admin einzeln schaltet.' },
  { kategorie: 'Abo & Paket', frage: 'Wann beginnt die Abrechnung?', antwort: 'Mit der Freischaltung: Nach der Registrierung wählst du unter „Abo“ ein Paket und hinterlegst die Zahlungsdaten, danach ist der Betrieb freigeschaltet. Abgerechnet wird monatlich ab diesem Tag über die hinterlegte Zahlungsart; eine kostenlose Testphase gibt es nicht. Bis zur Freischaltung, und wenn eine Zahlung nach allen Mahnungen offen bleibt, arbeitet der Betrieb im Nur-Lesen-Modus: alle Daten und Module bleiben sichtbar, Drucken und Exportieren gehen weiter, nur Speichern und die KI sind gesperrt, bis das Abo unter „Abo“ geklärt ist.' },
  { kategorie: 'Abo & Paket', frage: 'Was bedeutet „Nur-Lesen-Modus“?', antwort: 'Ist das Abo gesperrt (noch kein Paket gebucht, Zahlung nach allen Mahnungen offen oder gekündigt), zeigt jede Seite eine rote Hinweisleiste. Ansehen, Drucken und Exportieren (Behörden-CSV, BMD-Übergabe, Berichte) bleiben möglich – für Aufbewahrungspflicht und Datenauskunft. Gesperrt sind alle Änderungen sowie Frag dein Weingut und der Assistent (KI-Kosten); die BMD-Übergabe läuft dann ohne Protokoll und ohne neue Personenkonten. Benutzer entfernen, Profil, Zwei-Faktor und Betrieb wechseln gehen weiter. Nach der Zahlung unter „Abo“ ist der Betrieb sofort wieder frei.' },
  { kategorie: 'Abo & Paket', frage: 'Welche Rollen gibt es und was darf ein Mitarbeiter?', antwort: 'Betriebs-Manager (alles), Mitarbeiter (sieht alles außer System, bearbeitet nur in freigegebenen Modulen), Leser (nur ansehen) und Super-Admin (Plattformbetreiber). Die Module eines Mitarbeiters – Rieden, Kellerbuch, Warenwirtschaft, CRM, E&A-Rechnung, Controlling & Frag dein Weingut – setzt der Betriebs-Manager unter Mein Betrieb > Benutzer; die Vorlagen „Rieden & Keller“ und „Vertrieb“ sparen die Einzelauswahl. Bestehende Winzer/Kellermeister haben alle Module behalten.' },
  { kategorie: 'Abo & Paket', frage: 'Ein Mitarbeiter sieht Controlling und Frag dein Weingut nicht – warum?', antwort: 'Beides zeigt Umsätze und Margen des ganzen Betriebs. Mitarbeiter sehen es nur, wenn in ihrer Modulmatrix „Controlling & Frag dein Weingut“ angehakt ist (in der Vorlage „Vertrieb“ enthalten). Betriebs-Manager und Leser sehen es immer.' },
  { kategorie: 'Abo & Paket', frage: 'Wer ist der Super-Admin in meinem Betrieb und kann ich ihn entfernen?', antwort: 'Der Plattformbetreiber ist automatisch in jedem Betrieb als Super-Admin Mitglied – für Support und Einrichtung. Als Betriebs-Manager kannst du diese Mitgliedschaft unter Mein Betrieb > Benutzer auf Inaktiv setzen; dann hat der Super-Admin keinen Zugriff auf deine Daten mehr, bis du ihn wieder aktivierst.' },

  // Morgenbericht & Wetter
  { kategorie: 'Morgenbericht & Wetter', frage: 'Was prüft der Morgenbericht genau?', antwort: 'Jeden Tag um 7 Uhr: überfällige und fällige Fristen, Gärkontrollen, Rechnungen über Zahlungsziel, Belege ohne Kategorie und erkannte Belege, Buchungen mit ungewöhnlichem Betrag, negative Bestände, Pressungen vor Ablauf einer Wartefrist, mögliche Kontakt-Dubletten, Abo-Status – und das Wetter je Ried. Die Prüfungen sind feste Regeln; nur die Zusammenfassung schreibt die KI.' },
  { kategorie: 'Morgenbericht & Wetter', frage: 'Woher kommen die Wetterdaten?', antwort: 'Von GeoSphere Austria (Open Data): Rückblick aus der INCA-Analyse mit 1 km Auflösung, Prognose aus dem AROME-Modell mit 2,5 km, jeweils für die Koordinaten deiner Rieden (auf rund 2 km zusammengefasst). Das ist eine Flächenanalyse, keine Messung am Hof – lokale Schauer können abweichen.' },
  { kategorie: 'Morgenbericht & Wetter', frage: 'Warum sehe ich kein Wetter im Morgenbericht?', antwort: 'Drei mögliche Gründe: Deine Rieden haben keine Koordinaten (unter Rieden die Lage setzen oder aus dem eAMA importieren), Wetter & Empfehlungen ist unter Mein Betrieb > Branding abgeschaltet, oder das Paket ist Basis – Wetter gibt es ab Standard. Steht "keine Prognose", war GeoSphere gerade nicht erreichbar; der nächste Lauf holt sie nach.' },
  { kategorie: 'Morgenbericht & Wetter', frage: 'Was bedeutet "Spritzbelag abgewaschen" und woher weiß das System das?', antwort: 'software:112 summiert den Regen seit deiner letzten erfassten Spritzung je Ried. Ab 25 mm (einstellbar) gilt der Belag als abgewaschen, ab 60 % davon als nachlassend – eine Faustregel, kein Infektionsmodell. Ob wirklich Risiko besteht, sagt der Pflanzenschutz-Warndienst der Landwirtschaftskammer (warndienst.at), auf den der Bericht verlinkt.' },
  { kategorie: 'Morgenbericht & Wetter', frage: 'Was ist ein Spritzfenster?', antwort: 'Ein Zeitraum in den nächsten 48 Stunden, in dem laut Prognose zwischen 5 und 20 Uhr der Wind höchstens 15 km/h (Böen 30) hat, es nicht regnet und in den drei Stunden danach kein Regen kommt – also Ausbringung ohne Abdrift und Abwaschung möglich ist. Mindestens drei Stunden am Stück.' },
  { kategorie: 'Morgenbericht & Wetter', frage: 'Kann ich den Bericht sofort neu erstellen oder abschalten?', antwort: 'Betriebs-Manager und Mitarbeiter klicken auf der Übersicht "aktualisieren" – das frischt auch das Wetter auf und zählt bei KI-Zusammenfassung als eine Abfrage. Ein- und ausschalten sowie die Schwellwerte (Abwasch-Millimeter, Spritzintervall) findest du unter Mein Betrieb > Branding.' },
  { kategorie: 'Morgenbericht & Wetter', frage: 'Landen Morgenbericht-Befunde auch in der Glocke?', antwort: 'Dringende Befunde des Tages, die nicht schon als Frist oder Gärkontrolle in der Glocke stehen (z.B. abgewaschener Spritzbelag, Frostgefahr, negativer Bestand, offene Abo-Zahlung), erscheinen dort zusätzlich mit Link auf den Bericht.' },

  // Datenimport
  { kategorie: 'Datenimport', frage: 'Welche Formate werden für den CSV-Import unterstützt?', antwort: 'CSV-Dateien mit Semikolon (;) oder Komma (,) als Trennzeichen, UTF-8 Kodierung. Die meisten Excel-Exporte funktionieren direkt. Bei Problemen: in Excel "Speichern als > CSV UTF-8" wählen.' },
  { kategorie: 'Datenimport', frage: 'Was passiert mit Duplikaten beim Import?', antwort: 'Duplikate werden nicht automatisch erkannt – jede Zeile wird als neuer Datensatz angelegt. Prüfe vor dem Import deine CSV auf Duplikate, oder bereinige sie danach direkt in der Anwendung.' },

  // Maßnahmen
  { kategorie: 'Maßnahmen', frage: 'Warum sehe ich beim Toggle "Schnitt" kein BBCH-Stadium mehr?', antwort: 'Das Feld wurde für diese Maßnahmenart ausgeblendet, weil ein BBCH-Stadium beim Rebschnitt fachlich nicht relevant ist. Bei "Sonstiges" sind aus demselben Grund die Mengenfelder („Spritzbrühe gesamt (l)“ bzw. „Düngermenge gesamt (kg)“) ausgeblendet; statt „Schaderreger“ heißt das Feld dort „Grund / Anlass“ (Beispiel "z.B. Rodung"). Ein Pflanzenschutzmittel kannst du bei "Sonstiges" optional wählen (z.B. Pheromon-Dispenser) – dann gelten Bio-Sperre, Wartezeit und Behandlungsprotokoll wie bei einer Spritzung, und mit der optionalen Aufwandmenge (kg/ha, l/ha, kg oder l) zieht das Lager das Mittel ab. Bei "Bodenbearbeitung" ist das Gerät Pflicht, die Bearbeitungstiefe optional (Mulchen und Mähen haben keine Tiefe). Die Einarbeitung einer Düngung fragt das Formular nur bei organischem Dünger ab. Beim Bearbeiten zeigt das Formular dieselben Felder und Pflichtfelder wie beim Anlegen; eine schon gespeicherte Angabe in einem ausgeblendeten Feld (auch eine Einarbeitung „nein“) bleibt beim Speichern erhalten, solange du die Art nicht wechselst. Ausnahme bei den Pflichtfeldern: Hat eine ältere Maßnahme dort noch keinen Wert (z.B. kein Gerät), lässt sie sich unverändert speichern – Pflicht werden sie erst, wenn du die Art wechselst oder das Feld schon einen Wert hat.' },
  { kategorie: 'Maßnahmen', frage: 'Laubarbeit oder Laubschneiden – was wähle ich?', antwort: '„Laubschneiden“ ist das maschinelle Laubschneiden an Seiten und Gipfel (z.B. mit dem Laubschneider am Traktor). Alle anderen Arbeiten an der Laubwand erfasst du als „Laubarbeit“ und wählst dort die Art: Entblättern, Ausgeizen, Gipfeln, Heften oder Sonstige – das Gipfeln von Hand bleibt also eine Laubarbeit. Beim Laubschneiden gibt es keine „Art der Laubarbeit“, das BBCH-Stadium ist wie bei der Laubarbeit optional. Bereits erfasste Laubarbeiten bleiben unverändert. Beide Arten stehen getrennt in Auswertungen, Behandlungsprotokoll (Drucken und CSV), Weinbuch und Rückverfolgung und haben eigene Stundensätze.' },
  { kategorie: 'Maßnahmen', frage: 'Wie erfasse ich eine Tankmischung (mehrere Mittel in einer Spritzbrühe)?', antwort: 'Bei einer Spritzung das erste Mittel wählen und mit „+ weiteres Mittel (Tankmischung)“ jedes weitere Mittel samt Aufwandmenge hinzufügen. Datum, Rieden, Spritzbrühe bzw. Wasseraufwand und Anwendung gelten für alle Mittel. Gespeichert wird je Mittel eine Maßnahme – so rechnen Lager, Kupfer-Bilanz und Pflanzenschutz-Aufzeichnung je Mittel richtig. In der Liste stehen die Mittel zusammen (Kennzeichen „Tankmischung 1/2“); „Tankmischung stornieren“ storniert alle Mittel auf einmal.' },
  { kategorie: 'Maßnahmen', frage: 'Was trage ich bei „Menge gesamt“ ein?', antwort: 'Das hängt von der Art der Maßnahme ab. Spritzung: die gesamte Spritzbrühe in Litern (Mittel + Wasser) im Feld „Spritzbrühe gesamt (l)“ – nicht die Menge des Pflanzenschutzmittels; kg oder g nimmt software:112 dort nicht an. Statt der Spritzbrühe gesamt genügt der „Wasseraufwand (l/ha)“ (= Spritzbrühe je ha, Mittel + Wasser) – das jeweils andere Feld rechnet software:112 mit der Fläche der gewählten Grundstücke aus. Pflicht sind außerdem Mittel und Aufwandmenge, denn die Mittelmenge ergibt sich nur aus dem Aufwand: kg/ha bzw. l/ha × Fläche, kg bzw. l gesamt oder – bei g/hl bzw. ml/hl („Konzentration im Tank“, die tatsächliche Konzentration in der Brühe, nicht der Etikettwert) – Konzentration × Spritzbrühe ÷ 100. Beispiel: Funguran Progress 0,6 kg/ha auf 2 ha mit 400 l/ha ergibt 800 l Spritzbrühe und 1,2 kg Mittel. Aufwandmenge (kg/ha bzw. l/ha), Konzentration (%) und Wasseraufwand hängen zusammen – Aufwand = Wasseraufwand × Konzentration ÷ 100 –, je zwei davon ergeben die dritte: Das Formular rechnet das Feld aus, das du nicht als eines der zwei zuletzt eingegeben hast, und sperrt es („Automatisch berechnet aus …“); wer ein anderes Feld rechnen lassen will, leert eines der beiden eingegebenen. Beispiel: 2 l/ha und 0,5 % ergeben 400 l/ha Wasseraufwand, auf 1,5 ha also 600 l Spritzbrühe gesamt. Bei einer Tankmischung erfasst du je Mittel eine Maßnahme mit derselben Spritzbrühe. Düngung: die Düngermenge in kg im Feld „Düngermenge gesamt (kg)“ (Liter nur bei Düngemitteln, die in Litern geführt werden). Lager, Cu-Bilanz, Mittelverbrauch, Pflanzenschutz-Aufzeichnung und Materialkosten rechnen immer mit der Mittelmenge, nie mit der Spritzbrühe.' },
  { kategorie: 'Maßnahmen', frage: 'Warum wird ein Pflanzenschutzmittel im Maßnahmenformular gesperrt?', antwort: 'Das hängt vom Bio-Status deines Betriebs ab (Administration > Mandanten > Bewirtschaftung > Bio-Status). Bei Bio-EU oder Biodynamisch werden nicht öko-zugelassene Mittel automatisch gesperrt; bei KIP oder Nachhaltig erscheint nur eine Warnung, das Mittel bleibt aber wählbar. Der Grund steht direkt unter dem Mittel; ein Klick auf „Maßnahme erfassen“ springt dorthin, statt still gesperrt zu bleiben. Beim Bearbeiten macht „Änderungen speichern“ dasselbe; gespeichert wird dabei nichts.' },
  { kategorie: 'Maßnahmen', frage: 'Wie verteilt sich die Lesemenge, wenn ich mehrere Rieden oder Grundstücke auswähle?', antwort: 'Die „Menge kg gesamt“ gilt für die ganze Auswahl und wird nach Fläche auf alle gewählten Grundstücke aufgeteilt – egal ob du ganze Rieden, einzelne Grundstücke oder beides gewählt hast. Beispiel: 4.000 kg auf 0,5 + 0,5 ha (Ried A) und 1 ha (Ried B) ergibt 1.000 + 1.000 + 2.000 kg. Gerechnet wird in ganzen kg (bei einer Eingabe mit Komma in Zehntel bzw. Hundertstel), der Rundungsrest kommt auf die größte Fläche; die Summe entspricht genau deiner Eingabe. Die Vorschau im Formular zeigt die Aufteilung vor dem Speichern. Grundstücke ohne Fläche bekommen keinen Anteil – für sie oder für abweichende Mengen schaltest du „Mengen je Grundstück einzeln erfassen“ ein.' },
  { kategorie: 'Maßnahmen', frage: 'Was bedeutet die Hektarhöchstertrag-Warnung bei der Lese?', antwort: 'Für Qualitätswein gilt laut BKI ein Höchstertrag von 10.000 kg/ha, berechnet betriebsweit über die AMA-Gesamtfläche. Überschreitet die Summe deiner erfassten Erntemengen diesen Wert, erscheint in der Erntemeldung ein Hinweis – es handelt sich um eine reine Informations-/Warnfunktion, gespeichert wird die Menge trotzdem.' },
  { kategorie: 'Maßnahmen', frage: 'Wo pflege ich Düngemittel-Stammdaten?', antwort: 'Unter Rieden > Betriebsmittel > Tab "Düngemittel": Name, Handelsname, Typ, N-P-K-Gehalt, Wartezeit, Bio-Zulassung, Einarbeitungspflicht, Einheit (kg oder l – eine Düngermenge in Litern nimmt die Maßnahme nur bei Düngemitteln in l an) und Preis pro Einheit hinterlegen. Diese Werte stehen danach im Maßnahmenformular und in der Kosten-Vorschlagsfunktion zur Verfügung.' },
  { kategorie: 'Maßnahmen', frage: 'Wie lege ich Stundensätze für die Kosten-Vorschlagsfunktion fest?', antwort: 'Unter Rieden > Betriebsmittel > Tab "Stundensätze": je Maßnahmenart (z.B. Schnitt, Laubarbeit, Laubschneiden oder Bodenbearbeitung) einen Hektarsatz in Euro hinterlegen – etwa „Laubschneiden Seiten und Gipfel“ für den Laubschneider getrennt vom Satz für die Laubarbeit. Diese Sätze werden automatisch für den Personalkosten-Anteil im Vorschlag "Kosten erfassen" herangezogen: vorgeschlagen wird der erste aktive Satz der gewählten Art, gibt es mehrere, wählst du im Maßnahmenformular unter „Hektarsatz“ einen anderen.' },
  { kategorie: 'Maßnahmen', frage: 'Wie funktioniert die Kosten-Vorschlagsfunktion im Maßnahmenformular?', antwort: 'Im Abschnitt "Kosten erfassen" (unterhalb der Ried-Auswahl) schlägt software:112 automatisch Materialkosten (Preis je kg bzw. l × Mittelmenge – bei einer Spritzung aus dem Aufwand, nie aus der Spritzbrühe; lässt sich die Mittelmenge nicht berechnen, gibt es keinen Vorschlag, nur einen Hinweis) und Personalkosten (hinterlegter Hektarsatz × bearbeitete Fläche) vor. Der Vorschlag ist frei änderbar; bestätigst du ihn, wird beim Speichern der Maßnahme automatisch ein Kosteneintrag mit anteiliger Aufteilung auf die betroffenen Weingärten in der Kostenrechnung angelegt.' },
  { kategorie: 'Maßnahmen', frage: 'Warum ist "Ried(en) auswählen" im Maßnahmenformular eingeklappt?', antwort: 'Die Ried-Auswahl ist standardmäßig eingeklappt, damit der darunterliegende Abschnitt "Kosten erfassen" besser sichtbar ist. Über den Klick auf die Kopfzeile lässt sie sich jederzeit auf-/zuklappen; die Kopfzeile zeigt immer „noch keine Auswahl“ bzw. Anzahl und Fläche der gewählten Rieden und Grundstücke, auch im eingeklappten Zustand. Die Auswahl ist Pflicht: Klickst du ohne Auswahl auf „Maßnahme erfassen“, klappt der Abschnitt auf, der Fokus springt zur ersten Checkbox und die Meldung „Bitte mindestens ein Ried oder Grundstück auswählen.“ erscheint – gespeichert wird nichts.' },
  { kategorie: 'Maßnahmen', frage: 'Welche Maßnahmen zeigt die Rückverfolgung bei einer Lese?', antwort: 'Die Rückverfolgung zeigt je Lese die Maßnahmen des gelesenen Grundstücks „von Ernte bis Ernte“: ab dem Tag nach der letzten Lese des Vorjahrgangs an diesem Grundstück bis einschließlich zum Lesetag. Arbeiten nach der Vorjahres-Ernte – etwa ein Rebschnitt im Dezember oder eine Eiswein-Lese im Jänner – gehören damit zur nächsten Ernte. Hauptlese und Eiswein desselben Jahrgangs beginnen gleich, denn die Eiswein-Trauben hingen die ganze Saison am Stock. Als Vorjahres-Lese zählen das Lesedatum an der Pressung, die Erntemeldung und Traubenverkäufe. Ist für das Grundstück keine Lese des Vorjahrgangs erfasst (z. B. in der ersten Saison mit software:112), beginnt das Fenster am 01.01. des Jahrgangs; die Seite und die CSV weisen darauf hin.' },
  { kategorie: 'Maßnahmen', frage: 'Wie prüfe ich die Wartezeiten vor der Lese?', antwort: 'Unter Rieden > Rückverfolgung (auch aus der Lese, aus dem Weinbuch einer Charge und aus der Kellerbuch-Rückverfolgung einer Füllung erreichbar) siehst du je Lese-Grundstück alle Maßnahmen „von Ernte bis Ernte“. Bei Pflanzenschutzmitteln stehen Registernummer, Aufwand, Wartezeit und der früheste Lesetermin (letzter Behandlungstag plus Wartezeit). Liegt der Lesetag davor, ist die Zeile rot markiert („NICHT eingehalten“) und oben erscheint eine Warnung; grün heißt eingehalten. „Prüfen“ erscheint, wenn an der Pressung kein Lesedatum erfasst ist und nur das Pressungsdatum bekannt ist. Traubenverkäufe erscheinen mit Abnehmer und Liefernummer. Druck und CSV enthalten dieselben Angaben.' },

  // Kellerbuch
  { kategorie: 'Kellerbuch', frage: 'Wie wird die Qualitätsstufe einer neuen Charge bestimmt?', antwort: 'Bei der Lese wird die Qualitätsstufe aus dem KMW-Wert abgeleitet: Wein (unter 14 °KMW bzw. unter 67,9 °Oe), Landwein (ab 14 °KMW = 67,9 °Oe), Qualitätswein (ab 15 °KMW = 73,1 °Oe), Kabinett (ab 17 °KMW = 83,5 °Oe), Spätlese (ab 19 °KMW = 94,2 °Oe), Auslese (ab 21 °KMW = 105,0 °Oe), Beerenauslese (ab 25 °KMW = 127,3 °Oe), Trockenbeerenauslese (ab 30 °KMW = 156,0 °Oe); ohne KMW-Wert gilt Qualitätswein. Ein in °Oe gemessenes Mostgewicht zählt über den umgerechneten °KMW-Wert (auf 0,01 °KMW, gleichgesetzt wie in der BKI-Anreicherungstabelle: 83,5 °Oe = 17,00 °KMW) – die °Oe-Werte oben sind die kleinsten Messwerte der jeweiligen Stufe. Eiswein wird nie abgeleitet, sondern ist die Stufe einer Eiswein-Lese. An der Lese kannst du nur abstufen: wählbar sind die Stufen bis zur Obergrenze aus dem Mostgewicht und als Herkunft die Stufe des Grundstücks oder eine breitere (in der Sammelerfassung über „Abstufen auf“); die abgestufte Stufe geht so in die Erntemeldung. Bei der Lese stehen nur diese Stufen zur Wahl (Wein bis Trockenbeerenauslese und Eiswein). DAC, Reserve, Erste Lage, Großes Gewächs, Sekt, Perlwein und Sonstiges sind keine Lese-Stufen; sie gibt es beim Eröffnungsbestand, beim Zukauf von Wein bzw. Most, an der Charge und bei der Füllung. Eine Charge aus einer Pressung bekommt höchstens die niedrigste Stufe der verpressten Lese-Einträge bzw. die Stufe aus dem °KMW der Pressung; bei der Pressung kannst du weiter abstufen. Danach stufst du eine Charge über „Abstufen“ ab (an der Charge, im Kellerplan und über Strg K): Qualitätsstufe, Zusatzbezeichnung oder Herkunft, nur niedriger, mit Datum (rückdatierbar bis zum Kellerbuch-Abschluss) und Pflichtgrund – für die ganze Charge oder eine Teilmenge, die dazu in ein leeres Gebinde umgezogen wird. Die Abstufung steht im Weinbuch und im Änderungsprotokoll; eine geltende Prüfnummer erlischt dabei für den Tankbestand. Aufwerten ist nie möglich. Bei der Füllung bietet die Auswahl gegenüber der Charge nur dieselbe Stufe, niedrigere Stufen oder Sonstiges an; bei DAC, Reserve, Erste Lage, Großes Gewächs, Sekt und Perlwein nur dieselbe Bezeichnung oder Sonstiges. Ohne verknüpfte Charge oder bei einer Charge ohne Stufe stehen bei der Füllung alle Stufen zur Wahl.' },
  { kategorie: 'Kellerbuch', frage: 'Was passiert beim Verschnitt?', antwort: 'Wenn du Chargen verschiedener Qualitätsstufen mischt, wird die Ziel-Charge automatisch auf die niedrigste Qualitätsstufe aller Quellen gesetzt. Du bekommst eine Bestätigungsabfrage bevor der Umzug gespeichert wird.' },
  { kategorie: 'Kellerbuch', frage: 'Wie bekomme ich ein Etikett für meinen Wein?', antwort: 'Unter Kellerbuch > Prüfnummern: Den DAC-Antrag mit Prüfnummer öffnen, oben rechts auf "Etikett" klicken. Das System generiert ein druckfertiges Etikett mit allen Pflichtangaben und deinem Logo.' },
  { kategorie: 'Kellerbuch', frage: 'Wie lege ich eine neue Charge an?', antwort: 'Gar nicht direkt – Chargen entstehen ausschließlich automatisch, entweder durch eine Pressung (Kellerbuch > Pressungen > Pressung erfassen) oder durch eine Verschneidung bestehender Chargen. Der frühere Menüpunkt "Neue Charge" leitet dich automatisch zu den Pressungen weiter.' },
  { kategorie: 'Kellerbuch', frage: 'Warum sind manche Felder in der Charge grau und nicht editierbar?', antwort: 'Die Menge einer Charge ist im Formular nie direkt änderbar – sie ändert sich nur über datierte Buchungen (Umzug, Verschnitt, Füllung, Verkauf, Schwund). Stammt eine Charge aus einer Pressung, sind zusätzlich Jahrgang, Rebsorte, Qualitätsstufe, Weinart, Rieden und Behälter abgeleitet und gesperrt. Mostmenge und Behälter lassen sich in der Pressung nur ändern, solange an der Charge noch nichts gebucht wurde (Weinanalysen und DAC-Anträge sperren den Behälterwechsel nicht); danach bitte im Kellerbuch als eigene Buchung korrigieren.' },
  { kategorie: 'Kellerbuch', frage: 'Wie korrigiere ich die Menge einer Charge?', antwort: 'Nach unten über "Schwund buchen" auf der Chargen-Seite (datierte Buchung, bei 0 L wird die Charge abgeschlossen). Eine Korrektur nach oben (Mehrmenge, Inventur-Plus, Tippfehler im Eröffnungsbestand) bucht die Betriebsleitung auf der Chargen-Seite über "Zugang korrigieren": Menge, Datum, Art und Grund – im Kellerbuch als Inventurdifferenz Mehrmenge; eine geltende Prüfnummer gilt danach für den Tankbestand nicht mehr (Rückfrage vorher). Eine falsch erfasste Schwundbuchung können Betriebs-Manager und Mitarbeiter mit Kellerbuch im Umzugsprotokoll (Kellerbuch › Gebinde › Umziehen) mit Grund stornieren, solange an der Charge seither nichts weiter gebucht wurde.' },
  { kategorie: 'Kellerbuch', frage: 'Wann kann ich einen Umzug oder Verschnitt stornieren?', antwort: 'Solange die Ziel-Charge seither nicht weiterbewegt wurde (kein späterer Umzug, Verschnitt, Füllung, Verkauf oder Schwund) und die zurückzubuchende Menge noch vollständig vorhanden ist. Beim Storno gibst du einen Grund an (mindestens 10 Zeichen); die Quellen bekommen ihre Liter zurück (abgeschlossene werden wieder aktiv), das Ziel gibt sie ab, und die Buchung bleibt als storniert im Bewegungsbuch stehen. Klappt ein Schritt nicht, wird nichts geändert. Sonst bitte als Gegenbuchung korrigieren – ein Verschnitt lässt sich nicht per Umzug entmischen, die zu hohe Ziel-Charge dann über "Schwund buchen" korrigieren.' },
  { kategorie: 'Kellerbuch', frage: 'Kann ich Rotwein und Weißwein miteinander verschneiden?', antwort: 'Nein. Sobald du beim Verschneiden eine Quell-Charge mit gegensätzlicher Weinart auswählst, blockiert das System die Verschneidung mit einer roten Fehlermeldung ("Weinart-Konflikt") und der Speichern-Button ist deaktiviert.' },
  { kategorie: 'Kellerbuch', frage: 'Was bedeutet die 85%-Regel bei der Verschneidung?', antwort: 'Macht nach dem Verschnitt eine Rebsorte mindestens 85 % der Gesamtmenge aus, bleibt die Charge weiterhin sortenrein bezeichenbar ("bezeichnungsunschädlicher Verschnitt"). Liegt keine Sorte über dieser Schwelle, wird die Charge automatisch als "Sortenverschnitt" geführt – eine Live-Vorschau im Verschneiden-Formular zeigt dir das Ergebnis schon vor dem Speichern.' },
  { kategorie: 'Kellerbuch', frage: 'Wo finde ich Gebinde und Chargen, wenn sie nicht mehr in der Seitenleiste stehen?', antwort: 'Gebinde und die Chargenliste (Weinausbau) wurden aus der Kellerbuch-Sidebar entfernt, sind aber weiterhin erreichbar: über die Kacheln "Aktive Behälter" bzw. "Laufende Chargen" auf der Kellerbuch-Übersichtsseite, oder direkt über /kellerbuch/gebinde bzw. /kellerbuch/weinausbau.' },
  { kategorie: 'Kellerbuch', frage: 'Warum finde ich in der Kellerbuch-Übersicht keinen "Neue Füllung"-Button mehr?', antwort: 'Der Button wurde entfernt. Eine Charge füllst du stattdessen über den "Abfüllen"-Link direkt neben der jeweiligen Charge in der Kellerbuch-Übersicht bzw. über den "Abfüllen"-Button in der Charge-Detailseite ab.' },
  { kategorie: 'Kellerbuch', frage: 'Wie sehe ich, wie viel Platz in einem Gebinde noch frei ist?', antwort: 'Sowohl in der Kellerbuch-Übersicht (Kapazitätsbalken pro Behälter) als auch in den Behälter-Dropdowns bei Pressung, Umziehen und Verschneiden wird Kapazität, aktueller Inhalt und freier Rest in Liter direkt angezeigt.' },
  { kategorie: 'Kellerbuch', frage: 'Kann ein Gebinde auf mehreren Kellerplänen gleichzeitig stehen?', antwort: 'Nein. Ein Gebinde ist immer nur einem Standort (Kellerplan) zugeordnet – sobald es auf einem Kellerplan platziert ist, verschwindet es aus der Auswahl für alle anderen Kellerpläne, um Mehrfachzuordnungen zu vermeiden. Löschen lässt sich ein Gebinde nur, solange nie eine Charge darin lag (auch keine abgeschlossene oder die eines Partnerbetriebs) und keine Kellerbuch-Buchung (z. B. Kellerbehandlung, Pressung, Umzug) darauf verweist – sonst bitte über "Bearbeiten" auf "Inaktiv" setzen, so bleibt die Historie erhalten.' },
  { kategorie: 'Kellerbuch', frage: 'Was passiert, wenn ich im Kellerplan auf ein Gebinde klicke?', antwort: 'Ein Klick (kein Ziehen) auf ein Gebinde im Kellerplan öffnet ein Dialogfenster mit direkten Sprüngen zu "Umziehen", "Kellerbehandlungen" und – falls Wein enthalten ist – "Abfüllen". So kommst du aus der visuellen Kellerübersicht ohne Umweg direkt zur passenden Aktion.' },
  { kategorie: 'Kellerbuch', frage: 'Was passiert, wenn ich in ein Gebinde mit anderem Wein umziehe?', antwort: 'Liegt im Ziel-Gebinde bereits Wein mit anderer Rebsorte, anderem Jahrgang, anderer Herkunft oder Qualität – oder ziehst du mehrere verschiedene Chargen zusammen –, bucht das System den Umzug sofort als Verschnitt in die Charge im Ziel-Gebinde (bei leerem Gebinde in eine neue Charge). Das geht auch mit mehreren Ziel-Gebinden: Jedes Gebinde mit anderem Wein bekommt seinen eigenen Verschnitt – alle in einem Schritt, entweder alle oder keiner –, jedes Ziel erhält dieselbe Mischung der Quellen. Rebsorte und Jahrgang folgen der 85-%-Regel, Qualität und Herkunft werden bei Bedarf abgestuft; der Schwund wird anteilig bei den Quellen gebucht. Nach dem Buchen siehst du einen Hinweis mit allen Änderungen. Direkt nach einer Pressung in einen bereits befüllten Behälter öffnet sich weiterhin das Verschneiden-Formular.' },
  { kategorie: 'Kellerbuch', frage: 'Ich sehe Gebinde mit dem Namen eines anderen Weinguts – was ist das?', antwort: 'Das sind freigegebene Gebinde einer Kellergemeinschaft: Ein Partnerbetrieb (Eigentümer) hat euch seine Gebinde zur Nutzung freigegeben (eingerichtet vom Plattform-Admin unter Administration > Gemeinschaften). Du kannst dort deinen eigenen Wein einlagern und umziehen; vom Wein des Eigentümers oder anderer Partner siehst du nur "belegt" samt Litern – keine Details.' },
  { kategorie: 'Kellerbuch', frage: 'Warum kann ich nicht in ein bestimmtes Gebinde umziehen?', antwort: 'Liegt in einem Gebinde Wein eines anderen Betriebs (Kellergemeinschaft), ist es für alle anderen gesperrt – es erscheint in der Gebinde-Liste als "belegt · Betrieb" und fehlt in der Ziel-Auswahl. Erst wenn der andere Betrieb das Gebinde leer gemacht hat, ist es wieder frei. Zwei eigene Chargen im selben Gebinde sind weiterhin möglich (Verschnitt-Workflow).' },
  { kategorie: 'Kellerbuch', frage: 'Was macht der bawb.at-Button im Prüfnummern-Antrag genau?', antwort: 'Er öffnet nur das externe LFRZ-Portal (bawb.at, "Weinkontrolle Online") in einem neuen Tab als Schnellzugriff. Es werden keine Daten automatisch übertragen – Status und Prüfnummer musst du nach der Prüfung im Portal weiterhin manuell im Antrag eintragen.' },

  // Behördenmeldungen (Druck & CSV, 24.09.2026)
  { kategorie: 'Behördenmeldungen', frage: 'Wo finde ich die Behördenmeldungen und ihren CSV-Export?', antwort: 'Gesammelt unter Übersicht > Meldungen & Fristen in der Karte „Behördenmeldungen (Drucken & CSV)“ – dort stehen alle Meldungen, die deine Rolle abrufen darf, mit Link zur Seite und direktem CSV-Export. Auf jeder Meldungsseite (z. B. AMA-Erntemeldung, Behandlungsprotokoll, Weinbuch, Transportbescheinigung, UVA-Meldung) steht der CSV-Knopf neben „Drucken“ – beschriftet mit „CSV exportieren“ bzw., wenn eine Seite mehrere Dateien anbietet, mit „… als CSV“ (z. B. „Erntemeldung als CSV“, „Weinbestand als CSV“); die CSV enthält dieselben Daten wie der Ausdruck mit der Auswahl der Seite.' },
  { kategorie: 'Behördenmeldungen', frage: 'Ich bin Mitarbeiter und habe kein Modul Controlling – komme ich an die Pflichtmeldungen?', antwort: 'Ja. Weinerntemeldung, Lesedaten, Weinbestandsmeldung, Pflanzenschutz-Aufzeichnungen, Cu-Bilanz, Nährstoffbilanz und Weinbuch-Sammlung erreichen Super-Admins, Betriebs-Manager und Mitarbeiter samt Druck und CSV auch ohne Controlling – über Rieden > Maßnahmen > Behandlungsprotokoll, Cu-Bilanz und Nährstoffbilanz, Rieden > Lese (Lesedaten je Jahrgang), Rieden > Lese > AMA-Erntemeldung (Weinerntemeldung, Weinbestandsmeldung), Kellerbuch > Weinbuch-Sammlung oder die Karte unter Meldungen & Fristen. Leser brauchen dafür weiterhin das Modul Controlling mit Auswertungsrecht.' },
  { kategorie: 'Behördenmeldungen', frage: 'Excel zeigt die ganze CSV in einer einzigen Spalte – was tun?', antwort: 'Die Dateien trennen mit Semikolon und nutzen das Dezimalkomma, passend zu Excel mit Region Deutsch (Österreich). Steht Windows auf einer anderen Region, die Datei über „Daten › Aus Text/CSV“ öffnen und als Trennzeichen „Semikolon“ wählen.' },
  { kategorie: 'Behördenmeldungen', frage: 'Warum fehlt in Excel die führende Null bei KG-Nr. oder BBCH?', antwort: 'In der CSV stehen die Codes exakt (z. B. 04023 oder 05). Beim Öffnen per Doppelklick macht Excel daraus Zahlen und schneidet die Null ab. Für exakte Codes die Datei über „Daten › Aus Text/CSV“ importieren (Dateiursprung UTF-8, Trennzeichen Semikolon), „Daten transformieren“ wählen und die Spalten KG-Nr., GST-Nr., BBCH usw. als Text festlegen.' },
  { kategorie: 'Behördenmeldungen', frage: 'Warum steht vor manchen Texten in der CSV ein Apostroph?', antwort: 'Beginnt ein Text mit =, +, - oder @ (z. B. eine Telefonnummer „+43 …“ oder eine Notiz „-5 Grad“), setzt software:112 ein Apostroph davor. Sonst würde Excel den Inhalt als Formel ausführen – das ist ein Schutz gegen versehentliche oder eingeschleuste Formeln. Zahlen, Beträge und Datumsangaben sind davon nicht betroffen.' },
  { kategorie: 'Behördenmeldungen', frage: 'Die CSV enthält nur die Kopfzeile – ist das ein Fehler?', antwort: 'Nein, das ist eine Leermeldung: Für die gewählte Auswahl gibt es keine Datensätze (z. B. kein Traubenverkauf im Jahrgang oder – bei der Erntemeldung – ein Jahrgang ohne Lese). Der Knopf meldet dann „Leermeldung erstellt“; die Datei ist gültig und belegt die Nullmeldung. Bei reinen Listen (z. B. Behälter, Trefferliste) heißt es „Keine Datensätze“.' },
  { kategorie: 'Behördenmeldungen', frage: 'Was bedeuten die Hinweise nach dem CSV-Export?', antwort: 'Nach dem Download nennt der Knopf die Zahl der Zeilen und – falls nötig – Hinweise zum Prüfen, z. B. Rebsorten ohne amtliches BKI-Kürzel, Grundstücke ohne KG-Nummer, übersprungene Datensätze ohne Menge oder eine Transportbescheinigung, die noch nicht gespeichert wurde. Die Datei ist trotzdem erstellt; die Hinweise zeigen, wo die Stammdaten ergänzt werden sollten.' },
  { kategorie: 'Behördenmeldungen', frage: 'Ist die Weinbestandsmeldung ein Stichtagsbestand zum 31. Juli?', antwort: 'Noch nicht. Druck und CSV zeigen derzeit den Bestand am Tag des Abrufs; Dateiname und Hinweis sagen das ausdrücklich („kein Stichtagsbestand“). Die Berechnung zum Stichtag folgt mit einem späteren Update – bis dahin am 31. Juli abrufen oder die Mengen von Hand auf den Stichtag abgleichen.' },

  // Administration
  { kategorie: 'KI-Modul', frage: 'Kann ich aus einer KI-Ergebnisliste direkt zum Datensatz springen?', antwort: 'Ja – seit 18.9.2026 liefert die KI zu jeder Listenzeile die Kennungen der Datensätze mit. Die Zeile ist anklickbar und öffnet z.B. den Kontakt, die Firma, die Charge oder den Verkauf; bei mehreren verknüpften Datensätzen gibt es rechts in der Spalte "Öffnen" je eine Schaltfläche. Zeigt eine Liste keine Links, liefert die Abfrage nur Summen oder die KI hat die Kennungen weggelassen – dann die Frage etwas umformulieren ("zeig mir die Kontakte …").' },
  { kategorie: 'Administration', frage: 'Wo finde ich die Kundennummer eines Betriebs?', antwort: 'Unter Administration > Mandanten in der Spalte "Kundennummer" und im Kopf der Mandanten-Detailseite; der Betrieb selbst sieht sie unter System > Mein Betrieb und auf der Abo-Seite. Format S112-AT-<Kreis><lfd. Nr.>, der Kreis ist die erste Ziffer der Betriebs-PLZ. Fehlt die Nummer ("noch keine – PLZ fehlt"), unter Betrieb die Postleitzahl speichern – sie wird dann sofort vergeben und zusätzlich am Stripe-Kunden als Metadaten hinterlegt.' },
  { kategorie: 'Administration', frage: 'Wo trage ich die bawb.at-Zugangsdaten ein?', antwort: 'Unter Administration > Mandanten > [Betrieb] > Tab "bawb.at" hinterlegst du Kennung (Betriebsnummer) und Passwort für das LFRZ-Portal. Ein Button öffnet das Portal direkt in einem neuen Tab.' },

  // Technik
  { kategorie: 'Technik', frage: 'Ich sehe "This page could not load" - was tun?', antwort: 'Seite neu laden (F5). Falls es weiterhin passiert, melde dich aus- und wieder ein. Wenn das Problem bleibt, bitte den Administrator kontaktieren mit URL und Uhrzeit des Fehlers.' },
  { kategorie: 'Technik', frage: 'Funktioniert software:112 auch ohne Internet?', antwort: 'Nein, eine aktive Internetverbindung ist erforderlich. Alle Daten werden sicher in der Cloud (Supabase/Vercel, EU-Region Irland) gespeichert.' },
  { kategorie: 'Technik', frage: 'Wie exportiere ich meine Daten?', antwort: 'Unter Controlling > Datenexport: Kontakte, Firmen, Lagerbestand und Verkaufshistorie als CSV herunterladen – alle vier Semikolon-getrennt mit Dezimalkomma, Datum als TT.MM.JJJJ, UTF-8 mit BOM und Kopfzeile; sie öffnen in Excel (Region Deutsch/Österreich) per Doppelklick. Werte, die mit =, +, - oder @ beginnen (z. B. die Vorwahl „+43“), stehen zum Schutz vor Formeln mit vorangestelltem Apostroph in der Datei. Behördenmeldungen exportierst du auf ihrer Seite bzw. unter Meldungen & Fristen (siehe Kategorie Behördenmeldungen).' },
]

const KATEGORIEN = [...new Set(FAQS.map(f => f.kategorie))]

export default function FAQPage() {
  const [offen, setOffen] = useState<number | null>(null)
  const [suche, setSuche] = useState('')
  const [kategorie, setKategorie] = useState('Alle')

  const gefiltert = FAQS.filter(f =>
    (kategorie === 'Alle' || f.kategorie === kategorie) &&
    (!suche || f.frage.toLowerCase().includes(suche.toLowerCase()) || f.antwort.toLowerCase().includes(suche.toLowerCase()))
  )

  return (
    <div className="space-y-5 max-w-3xl">
      <div className="flex items-center gap-2 text-sm text-s112-muted">
        <span>Hilfe</span>
        <span>/</span>
        <span className="text-s112-text-1 font-medium">Häufige Fragen (FAQ)</span>
      </div>
      <div>
        <h1 className="text-2xl font-semibold text-s112-text">Häufige Fragen (FAQ)</h1>
        <p className="text-sm text-s112-muted mt-1">Antworten auf die häufigsten Fragen zu software:112 · Version 2.7 · Stand September 2026</p>
      </div>

      <div className="flex flex-wrap gap-3">
        <input value={suche} onChange={e => setSuche(e.target.value)}
          placeholder="Fragen durchsuchen…"
          className="border border-s112-border rounded-lg px-3 py-1.5 text-sm focus:outline-hidden focus:ring-2 focus:ring-s112-teal/40 w-56" />
        <div className="flex gap-1 flex-wrap">
          {['Alle', ...KATEGORIEN].map(k => (
            <button key={k} onClick={() => setKategorie(k)}
              className={`px-3 py-1.5 text-xs font-medium rounded-lg transition-colors
                ${kategorie === k ? 'bg-s112-teal text-s112-yellow' : 'bg-s112-bg text-s112-text-2 hover:bg-s112-teal/10'}`}>
              {k}
            </button>
          ))}
        </div>
      </div>

      <div className="space-y-2">
        {gefiltert.map((f, i) => (
          <div key={i} className="card overflow-hidden">
            <button onClick={() => setOffen(offen === i ? null : i)}
              className="w-full flex items-center justify-between px-5 py-3.5 text-left hover:bg-s112-bg/50 transition-colors">
              <div className="flex items-center gap-3">
                <span className="text-xs bg-s112-bg border border-s112-border px-2 py-0.5 rounded-sm text-s112-text-2 shrink-0">
                  {f.kategorie}
                </span>
                <span className="text-sm font-medium text-s112-text">{f.frage}</span>
              </div>
              <span className={`text-s112-muted shrink-0 ml-3 transition-transform ${offen === i ? 'rotate-180' : ''}`}>▾</span>
            </button>
            {offen === i && (
              <div className="px-5 pb-4 pt-1 text-sm text-s112-text-2 leading-relaxed border-t border-s112-border/40 whitespace-pre-line">
                {f.antwort}
              </div>
            )}
          </div>
        ))}
        {gefiltert.length === 0 && (
          <p className="text-center text-s112-muted py-8">Keine Fragen gefunden.</p>
        )}
      </div>

      <div className="text-center pt-2">
        <Link href="/hilfe/handbuch" className="text-sm text-s112-blue-700 hover:underline">
          Zum vollständigen Handbuch →
        </Link>
      </div>
    </div>
  )
}
